exact_script:
$ErrorActionPreference = 'Stop'
$workspace = [IO.Path]::GetFullPath($PSScriptRoot).TrimEnd('\')
$stage = (Resolve-Path -LiteralPath (Join-Path $workspace '.scratch\architecture-refactor-2026-10-18\ct-asymmetric-int4')).Path
$planPath = Join-Path $stage 'cleanup-plan.json'
if ((Get-FileHash -LiteralPath $planPath -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'e91ef0e8a3024b61378c7241095fee8c899e6da36d7dda090d6d12126bccfcad') { throw 'Cleanup plan changed' }
$plan = Get-Content -LiteralPath $planPath -Raw | ConvertFrom-Json
function Assert-Identity($row) {
    $item = Get-Item -LiteralPath $row.path -Force
    if ($item.PSIsContainer -or $item.Length -ne $row.bytes -or (Get-FileHash -LiteralPath $item.FullName -Algorithm SHA256).Hash.ToLowerInvariant() -ne $row.sha256) { throw "File differs: $($row.path)" }
}
$protected = @($plan.archive) + @($plan.retained_images) + @($plan.retained_references) + @($plan.link_plans)
foreach ($row in $protected) { Assert-Identity $row }
$inputPaths = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
foreach ($row in $plan.link_plans) {
    $link = Get-Content -LiteralPath $row.path -Raw | ConvertFrom-Json
    foreach ($inputRow in $link.inputs) { [void]$inputPaths.Add([IO.Path]::GetFullPath($inputRow.path)) }
}
foreach ($row in $plan.targets) {
    $item = Get-Item -LiteralPath $row.path -Force
    if (-not $item.FullName.StartsWith($stage + '\', [StringComparison]::OrdinalIgnoreCase) -or $item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw 'Unexpected target path' }
    $parent = $item.Directory
    while ($parent.FullName.StartsWith($workspace, [StringComparison]::OrdinalIgnoreCase)) {
        if ($parent.Attributes -band [IO.FileAttributes]::ReparsePoint) { throw 'Reparse point in target ancestry' }
        if ($parent.FullName -eq $workspace) { break }
        $parent = $parent.Parent
    }
    if ($inputPaths.Contains($item.FullName)) { throw 'Target is an actual retained link input' }
    Assert-Identity $row
}
foreach ($row in $plan.targets) { Remove-Item -LiteralPath $row.path -Force }
foreach ($row in $plan.targets) { if (Test-Path -LiteralPath $row.path) { throw 'Target remains' } }
foreach ($row in $plan.retained_images) { Assert-Identity $row }
foreach ($row in $plan.retained_references) { if (-not (Test-Path -LiteralPath $row.path)) { throw 'Reference disappeared' } }
@{ deleted_files = $plan.count; deleted_bytes = $plan.total_bytes; recursive = $false; retained_images = $plan.retained_images; reference_vectors_retained = @($plan.retained_references).Count; all_link_inputs_retained = $true; archive = $plan.archive } | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath (Join-Path $stage 'cleanup-result.json') -Encoding utf8
Write-Output "CT_RECLAIMED $($plan.count) files / $($plan.total_bytes) bytes"
